import os
import sys

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".codex", "skills", "docx"))

from scripts.document import Document

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

doc = Document("unpacked")
editor = doc["word/document.xml"]
dom = editor.dom


def is_element(node, name):
    return node.nodeType == 1 and node.namespaceURI == W and node.localName == name


headlines = []
for p in dom.getElementsByTagNameNS(W, "p"):
    texts = []
    for t in p.getElementsByTagNameNS(W, "t"):
        if t.firstChild and t.firstChild.nodeType == 3:
            texts.append(t.firstChild.data)
    text = "".join(texts)
    if text and text.isupper():
        for r in p.getElementsByTagNameNS(W, "r"):
            run_has_text = any(
                t.firstChild and t.firstChild.nodeType == 3 and t.firstChild.data.strip()
                for t in r.getElementsByTagNameNS(W, "t")
            )
            if not run_has_text:
                continue
            rpr = None
            for child in r.childNodes:
                if is_element(child, "rPr"):
                    rpr = child
                    break
            if rpr is None:
                rpr = dom.createElementNS(W, "w:rPr")
                r.insertBefore(rpr, r.firstChild)
            if not any(is_element(c, "u") for c in rpr.childNodes):
                u = dom.createElementNS(W, "w:u")
                u.setAttributeNS(W, "w:val", "single")
                rpr.appendChild(u)
        headlines.append(text)

print("Headlines underlined: %d" % len(headlines))
for h in headlines:
    print("  - %s" % h)

doc.save()
print("Saved.")

